// Generated by Claude Sonnet 5. Not hand-written by the project author.

import { BenchmarkResult } from './types';
import { median } from './stats';

function pad(value: string, width: number): string {
  return value.length >= width ? value + ' ' : value.padEnd(width);
}

export function printBenchmarkReport(results: BenchmarkResult[]): void {
  const columns = ['Benchmark', 'Native (ms)', 'Wasm (ms)', 'Wasm / Native', 'VM-reported (s)'];
  const widths = [22, 14, 14, 16, 16];

  console.log(columns.map((c, i) => pad(c, widths[i])).join(''));
  console.log(widths.reduce((a, w) => a + w, 0) > 0 ? '-'.repeat(widths.reduce((a, w) => a + w, 0)) : '');

  for (const r of results) {
    const nativeMedian = r.nativeTimingsMs && r.nativeTimingsMs.length > 0 ? median(r.nativeTimingsMs) : null;
    const wasmMedian = r.wasmTimingsMs.length > 0 ? median(r.wasmTimingsMs) : null;
    const ratio = nativeMedian !== null && wasmMedian !== null ? `${(wasmMedian / nativeMedian).toFixed(2)}x` : 'n/a';

    const row = [
      r.name,
      nativeMedian !== null ? nativeMedian.toFixed(2) : 'n/a',
      wasmMedian !== null ? wasmMedian.toFixed(2) : 'n/a',
      ratio,
      r.reportedVmSeconds !== null ? r.reportedVmSeconds.toFixed(4) : 'n/a',
    ];

    console.log(row.map((c, i) => pad(c, widths[i])).join(''));
  }
}
